d_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('afnan-hamimi-taib-azamudden','ahmad-fakhruddin-fakhrurazi','awang-hashim') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0004: concurrent ownership or identity change'; end if; end $$;

commit;
